if(!el.category)return;
const labels={ru:{all:'Вся продукция',pipes:'Стальные трубы',metal:'Металлопрокат',fittings:'Отводы и детали',m:'метр',kg:'килограмм',t:'тонна',pc:'штука',choose:'Выберите продукцию',request:'Цена по запросу',available:'Уточнить наличие',price:'за',sum:'Предварительная сумма',empty:'Ничего не найдено'},kk:{all:'Барлық өнім',pipes:'Болат құбырлар',metal:'Металл прокаты',fittings:'Бұрмалар мен бөлшектер',m:'метр',kg:'килограмм',t:'тонна',pc:'дана',choose:'Өнімді таңдаңыз',request:'Бағасы сұраныс бойынша',available:'Бар-жоғын нақтылау',price:'үшін',sum:'Алдын ала сома',empty:'Ештеңе табылмады'}};
const kkName=s=>s.replaceAll('Труба','Құбыр').replaceAll('оцинкованная','мырышталған').replaceAll('новая','жаңа').replaceAll('новый','жаңа').replaceAll('б/у','қолданылған').replaceAll('бесшовная','жіксіз').replaceAll('электросварная','электрмен дәнекерленген').replaceAll('лежалая','қоймада сақталған').replaceAll('восстановленная','қалпына келтірілген').replaceAll('вода','су').replaceAll('газ','газ').replaceAll('нефть','мұнай').replaceAll('стенка','қабырға').replaceAll('Длина','Ұзындығы').replaceAll('Отвод','Бұрма').replaceAll('Полуотвод','Жартылай бұрма').replaceAll('Тройник','Үштік').replaceAll('Переход','Өтпе').replaceAll('Фланец','Фланец').replaceAll('Кран шаровой','Шарлы кран').replaceAll('Задвижка','Ысырма').replaceAll('Лист стальной','Болат табақ').replaceAll('Уголок','Бұрыштық').replaceAll('Швеллер','Швеллер').replaceAll('Рулон алюминиевого листа','Алюминий табақ орамы');
const lang=()=>document.documentElement.lang==='kk'?'kk':'ru';
const textItem=item=>lang()==='kk'?kkName(item.name):item.name;
const money=n=>new Intl.NumberFormat(lang()==='kk'?'kk-KZ':'ru-KZ',{maximumFractionDigits:0}).format(Math.round(n))+' ₸';
function fillCategories(){const l=labels[lang()],value=el.category.value||'all';el.category.innerHTML=['all','pipes','metal','fittings'].map(k=>`<option value="${k}">${l[k]}</option>`).join('');el.category.value=value;}
function filtered(){const q=el.search.value.trim().toLowerCase();return items.filter(x=>(el.category.value==='all'||x.category===el.category.value)&&(!q||textItem(x).toLowerCase().includes(q)||x.name.toLowerCase().includes(q)));}
function fillProducts(keep=true){const old=keep?el.product.value:'';const list=filtered();el.product.innerHTML=list.map(x=>`<option value="${items.indexOf(x)}">${textItem(x)}</option>`).join('');if(old&&[...el.product.options].some(o=>o.value===old))el.product.value=old;if(!el.product.value&&el.product.options.length)el.product.selectedIndex=0;render();}
function selected(){return items[Number(el.product.value)];}
function unitsFor(item){const units=Object.keys(item?.prices||{});if(units.includes('t'))units.splice(units.indexOf('t'),0,'kg');return units;}
function unitPrice(item,unit){return unit==='kg'?item.prices.t/1000:item.prices[unit];}
function fillUnits(item){const old=el.unit.value;el.unit.innerHTML=unitsFor(item).map(k=>`<option value="${k}">${labels[lang()][k]}</option>`).join('');if([...el.unit.options].some(o=>o.value===old))el.unit.value=old;}
function render(){const l=labels[lang()],item=selected();fillUnits(item);if(!item){el.total.textContent='—';el.breakdown.textContent=filtered().length?l.choose:l.empty;el.note.textContent='';return;}const units=unitsFor(item);if(!units.length){el.total.textContent=l.request;el.breakdown.textContent=textItem(item);el.note.textContent=lang()==='kk'?'Нақты бағаны менеджерден сұраңыз.':'Уточните актуальную стоимость у менеджера.';}else{const unit=el.unit.value||units[0],qty=Math.max(0,Number(el.quantity.value)||0),price=unitPrice(item,unit);el.total.textContent=money(price*qty);el.breakdown.textContent=`${money(price)} ${l.price} ${l[unit]} × ${new Intl.NumberFormat(lang()==='kk'?'kk-KZ':'ru-KZ').format(qty)}`;el.note.textContent=lang()==='kk'?kkName(item.note):item.note;}const message=lang()==='kk'?`Сәлеметсіз бе! ${textItem(item)} бойынша бар-жоғын және бағасын нақтылағым келеді. Саны: ${el.quantity.value} ${el.unit.options[el.unit.selectedIndex]?.text||''}.`:`Здравствуйте! Хочу уточнить наличие и цену: ${item.name}. Количество: ${el.quantity.value} ${el.unit.options[el.unit.selectedIndex]?.text||''}.`;el.whatsapp.href=`https://wa.me/77479000955?text=${encodeURIComponent(message)}`;el.whatsapp.childNodes[0].nodeValue=l.available+' ';}
